            ? (value as { from: Date | undefined; to?: Date })
            : undefined
        }
        onValueChange={onValueChange}
        disabled={disabled}
      />
    )
  }
  if (type === 'upload')
    return (
      <Upload
        fileList={Array.isArray(value) ? value : []}
        onFileListChange={onValueChange}
        disabled={disabled}
      />
    )
  if (type === 'textarea')
    return (
      <Textarea
        id={id}
        aria-label={id ? undefined : (placeholder ?? 'Field value')}
        aria-invalid={invalid}
        value={String(value ?? '')}
        onChange={(e) => onValueChange?.(e.target.value)}
        placeholder={placeholder}
        disabled={disabled}
      />
    )
  if (type === 'switch')
    return (
      <Switch
        id={id}
        checked={!!value}
        onCheckedChange={onValueChange}
        disabled={disabled}
        aria-invalid={invalid}
      />
    )
  if (type === 'checkbox')
    return (
      <Checkbox
        id={id}
        checked={!!value}
        onCheckedChange={onValueChange}
        disabled={disabled}
        aria-invalid={invalid}
      />
    )
  if (type === 'select')
    return (
      <Combobox
        id={id}
        value={value ? [String(value)] : []}
        onValueChange={(v) => onValueChange?.(v[0] ?? '')}
        options={options}
        placeholder={placeholder}
        disabled={disabled}
      />
    )
  if (type === 'rate')
    return <Rate value={Number(value) || 0} onValueChange={onValueChange} disabled={disabled} />
  return (
    <Input
      id={id}
      aria-label={id ? undefined : (placeholder ?? 'Field value')}
      aria-invalid={invalid}
      type={
        type === 'datetime'
          ? 'datetime-local'
          : ['money', 'percent', 'number'].includes(type)
            ? 'number'
            : type
      }
      value={String(value ?? '')}
      onChange={(e) =>
        onValueChange?.(
          ['money', 'percent', 'number'].includes(type)
            ? e.target.value === ''
              ? ''
              : e.target.valueAsNumber
            : e.target.value,
        )
      }
      placeholder={placeholder}
      disabled={disabled}
    />
  )
}

