        const next = e.target.valueAsNumber
        if (Number.isInteger(next) && next >= min && next <= max) onValueChange?.(next)
      }}
      onBlur={() => {
        const next = Number(draft)
        if (!Number.isInteger(next) || next < min || next > max)
          setDraft(value === undefined ? '' : String(value))
      }}
      disabled={disabled}
    />
  )
