import { enUS, id, de, fr, ja } from 'date-fns/locale'
export const dateLocales = { 'en-US': enUS, 'id-ID': id, 'de-DE': de, 'fr-FR': fr, 'ja-JP': ja }
export const getDateLocale = (locale: string) =>
  dateLocales[locale as keyof typeof dateLocales] ?? enUS
export function toZonedInput(date: Date, timeZone: string) {
  if (!Number.isFinite(+date)) return ''
  const parts = new Intl.DateTimeFormat('en-CA', {
      timeZone,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
      hourCycle: 'h23',
    }).formatToParts(date),
    part = (type: string) => parts.find((p) => p.type === type)?.value
  return `${part('year')}-${part('month')}-${part('day')}T${part('hour')}:${part('minute')}:${part('second')}`
}
export function fromZonedInput(text: string, timeZone: string) {
  if (!/^\d{4}-\d\d-\d\dT\d\d:\d\d(?::\d\d)?$/.test(text))
    throw new Error('Enter a valid date and time')
  const normalized = text.length === 16 ? text + ':00' : text,
    wall = Date.parse(normalized + 'Z'),
    matches: number[] = []
  for (let offset = -36; offset <= 36; offset += 6) {
    const sample = wall + offset * 3600000,
      zoneWall = Date.parse(toZonedInput(new Date(sample), timeZone) + 'Z'),
      candidate = wall - (zoneWall - sample)
    if (toZonedInput(new Date(candidate), timeZone) === normalized) matches.push(candidate)
  }
  if (!matches.length) throw new Error('This local time does not exist in the selected time zone')
  return new Date(Math.min(...matches))
}

import * as React from 'react'
import { ChevronsUpDown } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover'
import { Tree, flattenTree, type TreeNode } from '@/components/ui/tree'
import { useControllableState } from '@/components/ui/util'
export function filterTree(nodes: TreeNode[], query: string): TreeNode[] {
  return nodes.flatMap((node) => {
    if (node.label.toLowerCase().includes(query.toLowerCase())) return [node]
    const children = node.children ? filterTree(node.children, query) : []
    return children.length ? [{ ...node, children }] : []
  })
}
export function TreeSelect({
  nodes,
  value,
  defaultValue = [],
  onValueChange,
  multiple,
  placeholder = 'Select from tree',
  disabled,
  searchable = true,
  virtual,
  loadChildren,
  maxTags = 3,
}: {
  nodes: TreeNode[]
  value?: string[]
  defaultValue?: string[]
  onValueChange?: (keys: string[]) => void
  multiple?: boolean
  placeholder?: string
  disabled?: boolean
  searchable?: boolean
  virtual?: boolean
  loadChildren?: (key: string) => Promise<void>
  maxTags?: number
}) {
  const [selected, setSelected] = useControllableState({
    value,
    defaultValue,
    onChange: onValueChange,
  })
  const [open, setOpen] = React.useState(false),
    [query, setQuery] = React.useState('')
  const all = flattenTree(nodes),
    filtered = query ? filterTree(nodes, query) : nodes
  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          variant="outline"
          role="combobox"
          aria-label={placeholder}
          aria-expanded={open}
          className="min-w-56 max-w-full justify-between font-normal"
          disabled={disabled}
        >
          <span className="truncate">
            {selected.length
              ? selected
                  .slice(0, maxTags)
                  .map((k) => all.find((n) => n.node.key === k)?.node.label)
                  .filter(Boolean)
                  .join(', ')
              : placeholder}
            {selected.length > maxTags ? ` +${selected.length - maxTags}` : ''}
          </span>
          <ChevronsUpDown size={14} />
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-72 p-1">
        {searchable && (
          <Input
            aria-label="Search tree options"
            placeholder="Search options…"
            className="mb-1 border-0 shadow-none"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
          />
        )}
        <Tree
          key={query ? 'search' : 'browse'}
          className="border-0"
          nodes={filtered}
          virtual={virtual}
          loadChildren={loadChildren}
          checkable={multiple}
          value={selected}
          onValueChange={setSelected}
          selectedKey={selected[0]}
          onSelect={(key) => {
            if (!multiple) {
              setSelected([key])
              setOpen(false)
            }
          }}
          defaultExpandedKeys={
            query ? flattenTree(filtered).map((n) => n.node.key) : nodes.map((n) => n.key)
          }
        />
        {filtered.length === 0 && (
          <p className="p-4 text-center text-sm text-muted-foreground">No options found.</p>
        )}
        {selected.length > 0 && (
          <Button size="sm" variant="ghost" className="w-full" onClick={() => setSelected([])}>
            Clear selection
          </Button>
        )}
      </PopoverContent>
    </Popover>
  )
}

import * as React from 'react'
import { useVirtualizer } from '@tanstack/react-virtual'
import { ChevronRight, Folder, File, Loader2 } from 'lucide-react'
import { Checkbox } from '@/components/ui/checkbox'
import { useControllableState } from '@/components/ui/util'
import { cn } from '@/lib/utils'
export interface TreeNode {
  key: string
  label: string
  children?: TreeNode[]
  disabled?: boolean
  isLeaf?: boolean
  icon?: React.ReactNode
}
export function flattenTree(
  nodes: TreeNode[],
  expanded?: string[],
  level = 0,
  parent?: string,
): { node: TreeNode; level: number; parent?: string }[] {
  return nodes.flatMap((node) => [
    { node, level, parent },
    ...(node.children && (!expanded || expanded.includes(node.key))
      ? flattenTree(node.children, expanded, level + 1, node.key)
      : []),
  ])
}
export function treeLeaves(node: TreeNode): string[] {
  return node.disabled ? [] : node.children?.length ? node.children.flatMap(treeLeaves) : [node.key]
}
export function canDropTreeNode(nodes: TreeNode[], source: string, target: string) {
  const flat = flattenTree(nodes),
    sourceNode = flat.find((n) => n.node.key === source)?.node,
    targetNode = flat.find((n) => n.node.key === target)?.node
  return (
    !!sourceNode &&
    !!targetNode &&
    !sourceNode.disabled &&
    !targetNode.disabled &&
    source !== target &&
    !flattenTree(sourceNode.children ?? []).some((n) => n.node.key === target)
  )
}
export interface TreeProps {
  nodes: TreeNode[]
  value?: string[]
  defaultValue?: string[]
  onValueChange?: (keys: string[]) => void
  expandedKeys?: string[]
  defaultExpandedKeys?: string[]
  onExpandedChange?: (keys: string[]) => void
  selectedKey?: string
  onSelect?: (key: string) => void
  checkable?: boolean
  virtual?: boolean
  height?: number
  className?: string
  loadChildren?: (key: string) => Promise<void>
  onNodeDrop?: (source: string, target: string, position: TreeDropPosition) => void
  onNodesChange?: (nodes: TreeNode[]) => void
  label?: string
}
export function Tree({
  nodes,
  value,
  defaultValue = [],
  onValueChange,
  expandedKeys,
  defaultExpandedKeys = [],
  onExpandedChange,
  selectedKey,
  onSelect,
  checkable,
  virtual,
  height = 300,
  className,
  loadChildren,
  onNodeDrop,
  onNodesChange,
  label = 'Tree',
}: TreeProps) {
  const [checked, setChecked] = useControllableState({
    value,
    defaultValue,
    onChange: onValueChange,
  })
  const [expanded, setExpanded] = useControllableState({
    value: expandedKeys,
    defaultValue: defaultExpandedKeys,
    onChange: onExpandedChange,
  })
  const [loading, setLoading] = React.useState<string[]>([])
  const [error, setError] = React.useState('')
  const [focused, setFocused] = React.useState<string>()
  const [drop, setDrop] = React.useState<{ key: string; position: TreeDropPosition }>()
  const container = React.useRef<HTMLDivElement>(null)
  const flat = flattenTree(nodes, expanded)
  const rowVirtualizer = useVirtualizer({
    count: flat.length,
    getScrollElement: () => container.current,
    estimateSize: () => 36,
    overscan: 6,
    enabled: !!virtual,
  })
  const toggle = async (node: TreeNode) => {
    if (expanded.includes(node.key)) {
      setExpanded(expanded.filter((k) => k !== node.key))
      return
    }
    if (!node.children?.length && !node.isLeaf && loadChildren) {
      setLoading((p) => [...p, node.key])
      try {
        await loadChildren(node.key)
      } catch (e) {
        setError(String(e))
        return
      } finally {
        setLoading((p) => p.filter((k) => k !== node.key))
      }
    }
    setExpanded([...expanded, node.key])
  }
  const focusNode = (index: number) => {
    const target = flat[Math.max(0, Math.min(flat.length - 1, index))]
    if (!target) return
    setFocused(target.node.key)
    if (virtual) rowVirtualizer.scrollToIndex(index)
    requestAnimationFrame(() =>
      container.current
        ?.querySelector<HTMLElement>(`[data-tree-key="${CSS.escape(target.node.key)}"]`)
        ?.focus(),
    )
  }
  const render = ({ node, level }: (typeof flat)[number], index: number) => {
    const leaves = treeLeaves(node)
    const full = leaves.length > 0 && leaves.every((k) => checked.includes(k))
    const partial = leaves.some((k) => checked.includes(k))
    const branch = !!node.children?.length || (!node.isLeaf && !!loadChildren)
    return (
      <div
        key={node.key}
        role="treeitem"
        data-tree-key={node.key}
        aria-level={level + 1}
        aria-selected={selectedKey === node.key}
        aria-expanded={branch ? expanded.includes(node.key) : undefined}
        aria-checked={checkable ? (full ? true : partial ? 'mixed' : false) : undefined}
        aria-disabled={node.disabled}
        tabIndex={(focused ?? flat[0]?.node.key) === node.key ? 0 : -1}
        draggable={!!(onNodeDrop || onNodesChange) && !node.disabled}
        onDragStart={(e) => e.dataTransfer.setData('text/plain', node.key)}
        onDragEnd={() => setDrop(undefined)}
        onDragOver={(e) => {
          if (onNodeDrop || onNodesChange) {
            e.preventDefault()
            const rect = e.currentTarget.getBoundingClientRect(),
              ratio = (e.clientY - rect.top) / rect.height
            setDrop({
              key: node.key,
              position: ratio < 0.25 ? 'before' : ratio > 0.75 ? 'after' : 'inside',
            })
          }
        }}
        onDrop={(e) => {
          e.preventDefault()
          const key = e.dataTransfer.getData('text/plain')
          const position = drop?.key === node.key ? drop.position : 'inside'
          if (canDropTreeNode(nodes, key, node.key)) {
            onNodeDrop?.(key, node.key, position)
            onNodesChange?.(moveTreeNode(nodes, key, node.key, position))
          }
          setDrop(undefined)
        }}
        onFocus={() => setFocused(node.key)}
        onKeyDown={(e) => {
          if (e.target !== e.currentTarget) return
          const current = flat.findIndex((n) => n.node.key === node.key)
          if (
            e.altKey &&
            ['ArrowUp', 'ArrowDown'].includes(e.key) &&
            (onNodeDrop || onNodesChange)
          ) {
            e.preventDefault()
            const siblings = flat.filter((item) => item.parent === flat[current].parent),
              at = siblings.findIndex((item) => item.node.key === node.key),
              target = siblings[at + (e.key === 'ArrowUp' ? -1 : 1)]?.node,
              position = e.key === 'ArrowUp' ? 'before' : 'after'
            if (target && canDropTreeNode(nodes, node.key, target.key)) {
              onNodeDrop?.(node.key, target.key, position)
              onNodesChange?.(moveTreeNode(nodes, node.key, target.key, position))
            }
            return
          }
          if (e.key === 'ArrowDown') {
            e.preventDefault()
            focusNode(current + 1)
          }
          if (e.key === 'ArrowUp') {
            e.preventDefault()
            focusNode(current - 1)
          }
          if (e.key === 'Home') {
            e.preventDefault()
            focusNode(0)
          }
          if (e.key === 'End') {
            e.preventDefault()
            focusNode(flat.length - 1)
          }
          if (e.key === 'ArrowRight' && branch) {
            e.preventDefault()
            if (!expanded.includes(node.key)) void toggle(node)
            else focusNode(current + 1)
          }
          if (e.key === 'ArrowLeft') {
            e.preventDefault()
            if (expanded.includes(node.key)) void toggle(node)
            else {
              const parent = flat[current].parent
              if (parent) focusNode(flat.findIndex((n) => n.node.key === parent))
            }
          }
          if ((e.key === 'Enter' || e.key === ' ') && !node.disabled) {
            e.preventDefault()
            if (checkable) {
              setChecked(
                full
                  ? checked.filter((k) => !leaves.includes(k))
                  : [...new Set([...checked, ...leaves])],
              )
            } else onSelect?.(node.key)
          }
        }}
        className={cn(
          'flex h-9 items-center gap-1.5 rounded-md pr-2 text-sm outline-none hover:bg-muted focus-visible:ring-2 focus-visible:ring-ring',
          selectedKey === node.key && 'bg-primary/10 text-primary',
          node.disabled && 'opacity-40',
          drop?.key === node.key &&
            (drop.position === 'inside'
              ? 'bg-primary/15 ring-1 ring-primary'
              : drop.position === 'before'
                ? 'border-t-2 border-primary'
                : 'border-b-2 border-primary'),
        )}
        style={{
          paddingInlineStart: level * 20 + 4,
          ...(virtual ? { position: 'absolute', top: index * 36, width: '100%' } : {}),
        }}
      >
        <button
          type="button"
          tabIndex={-1}
          disabled={!branch || node.disabled}
          aria-label={`${expanded.includes(node.key) ? 'Collapse' : 'Expand'} ${node.label}`}
          onClick={() => void toggle(node)}
          className={cn('flex size-6 items-center justify-center', !branch && 'invisible')}
        >
          {loading.includes(node.key) ? (
            <Loader2 size={13} className="animate-spin" />
          ) : (
            <ChevronRight
              size={14}
              className={cn('transition', expanded.includes(node.key) && 'rotate-90')}
            />
          )}
        </button>
        {checkable && (
          <Checkbox
            tabIndex={-1}
            aria-label={`Select ${node.label}`}
            disabled={node.disabled}
            checked={full ? true : partial ? 'indeterminate' : false}
            onCheckedChange={() =>
              setChecked(
                full
                  ? checked.filter((k) => !leaves.includes(k))
                  : [...new Set([...checked, ...leaves])],
              )
            }
          />
        )}
        <span className="text-muted-foreground">
          {node.icon ?? (branch ? <Folder size={15} /> : <File size={15} />)}
        </span>
        <button
          type="button"
          tabIndex={-1}
          disabled={node.disabled}
          onClick={() => {
            onSelect?.(node.key)
            if (branch && !checkable) void toggle(node)
          }}
          className="flex-1 truncate text-left"
        >
          {node.label}
        </button>
      </div>
    )
  }
  return (
    <div>
      <div
        ref={container}
        role="tree"
        aria-label={label}
        aria-multiselectable={checkable}
        className={cn('overflow-auto rounded-lg border p-2', className)}
        style={{ height: virtual ? height : undefined, maxHeight: height }}
      >
        <div
          className="relative"
          style={{ height: virtual ? rowVirtualizer.getTotalSize() : undefined }}
        >
          {virtual
            ? rowVirtualizer.getVirtualItems().map((row) => render(flat[row.index], row.index))
            : flat.map(render)}
        </div>
      </div>
      {error && (
        <p role="alert" className="text-sm text-destructive">
          {error}
        </p>
      )}
    </div>
  )
}
export type TreeDropPosition = 'before' | 'inside' | 'after'
export function moveTreeNode(
  nodes: TreeNode[],
  source: string,
  target: string,
  position: TreeDropPosition,
): TreeNode[] {
  if (!canDropTreeNode(nodes, source, target)) return nodes
  let moving: TreeNode | undefined
  const remove = (items: TreeNode[]): TreeNode[] =>
    items.flatMap((node) => {
      if (node.key === source) {
        moving = node
        return []
      }
      return [{ ...node, ...(node.children ? { children: remove(node.children) } : {}) }]
    })
  const stripped = remove(nodes)
  if (!moving) return nodes
  const insert = (items: TreeNode[]): TreeNode[] =>
    items.flatMap((node) =>
      node.key === target
        ? position === 'before'
          ? [moving!, node]
          : position === 'after'
            ? [node, moving!]
            : [{ ...node, isLeaf: false, children: [...(node.children ?? []), moving!] }]
        : [{ ...node, ...(node.children ? { children: insert(node.children) } : {}) }],
    )
  return insert(stripped)
}

import * as React from 'react'
import { UploadCloud, X, FileText, Loader2, Check, RefreshCw } from 'lucide-react'
import { cn } from '@/lib/utils'
import { useControllableState } from '@/components/ui/util'
export interface UploadFile {
  id: string
  file: File
  status: 'ready' | 'uploading' | 'done' | 'error'
  error?: string
  progress?: number
  preview?: string
}
export interface UploadProps {
  accept?: string
  multiple?: boolean
  maxSize?: number
  maxCount?: number
  disabled?: boolean
  onFilesChange?: (files: File[]) => void
  customRequest?: (
    file: File,
    signal: AbortSignal,
    onProgress: (percent: number) => void,
  ) => Promise<void>
  directory?: boolean
  showThumbnails?: boolean
  className?: string
  fileList?: UploadFile[]
  defaultFileList?: UploadFile[]
  onFileListChange?: (files: UploadFile[]) => void
  beforeUpload?: (file: File) => File | false | Promise<File | false>
  paste?: boolean
}
export function Upload({
  accept,
  multiple = true,
  maxSize = 10 * 1024 * 1024,
  maxCount = 10,
  disabled,
  onFilesChange,
  customRequest,
  className,
  directory,
  showThumbnails = true,
  fileList,
  defaultFileList = [],
  onFileListChange,
  beforeUpload,
  paste = true,
}: UploadProps) {
  const [files, setFiles] = useControllableState<UploadFile[]>({
    value: fileList,
    defaultValue: defaultFileList,
    onChange: onFileListChange,
  })
  const [error, setError] = React.useState('')
  const [drag, setDrag] = React.useState(false)
  const input = React.useRef<HTMLInputElement>(null)
  const requests = React.useRef(new Map<string, AbortController>())
  const previews = React.useRef(new Map<string, string>())
  React.useEffect(
    () => () => {
      requests.current.forEach((c) => c.abort())
      previews.current.forEach((url) => URL.revokeObjectURL(url))
    },
    [],
  )
  const start = (entry: UploadFile) => {
    if (!customRequest) return
    const controller = new AbortController()
    requests.current.set(entry.id, controller)
    setFiles((files) =>
      files.map((f) =>
        f.id === entry.id ? { ...f, status: 'uploading', error: undefined, progress: 0 } : f,
      ),
    )
    Promise.resolve()
      .then(() =>
        customRequest(entry.file, controller.signal, (percent) => {
          if (!controller.signal.aborted)
            setFiles((files) =>
              files.map((f) =>
                f.id === entry.id ? { ...f, progress: Math.max(0, Math.min(100, percent)) } : f,
              ),
            )
        }),
      )
      .then(() => {
        if (!controller.signal.aborted)
          setFiles((files) =>
            files.map((f) => (f.id === entry.id ? { ...f, status: 'done', progress: 100 } : f)),
          )
      })
      .catch((error) => {
        if (!controller.signal.aborted)
          setFiles((files) =>
            files.map((f) =>
              f.id === entry.id
                ? {
                    ...f,
                    status: 'error',
                    error: error instanceof Error ? error.message : String(error),
                  }
                : f,
            ),
          )
      })
      .finally(() => requests.current.delete(entry.id))
  }
  const add = async (incoming: File[]) => {
    if (disabled) return
    setError('')
    const available = (multiple ? maxCount : 1) - files.length
    const accepted: UploadFile[] = []
    for (let file of incoming) {
      if (beforeUpload) {
        try {
          const result = await beforeUpload(file)
          if (result === false) continue
          file = result
        } catch (error) {
          setError(String(error))
          continue
        }
      }
      const types = accept?.split(',').map((t) => t.trim().toLowerCase())
      const valid =
        !types ||
        types.some((t) =>
          t.startsWith('.')
            ? file.name.toLowerCase().endsWith(t)
            : t.endsWith('/*')
              ? file.type.startsWith(t.slice(0, -1))
              : file.type === t,
        )
      if (file.size > maxSize) {
        setError(`${file.name} exceeds ${(maxSize / 1024 / 1024).toFixed(0)} MB.`)
        continue
      }
      if (!valid) {
        setError(`${file.name} is not an accepted file type.`)
        continue
      }
      if (accepted.length >= available) {
        setError(`Choose at most ${multiple ? maxCount : 1} files.`)
        break
      }
      const id = crypto.randomUUID(),
        preview =
          showThumbnails && file.type.startsWith('image/') ? URL.createObjectURL(file) : undefined
      if (preview) previews.current.set(id, preview)
      accepted.push({
        id,
        file,
        preview,
        status: customRequest ? 'uploading' : 'ready',
      })
    }
    const next = [...files, ...accepted]
    setFiles(next)
    onFilesChange?.(next.map((f) => f.file))
    accepted.forEach(start)
  }
  return (
    <div
      className={cn('w-full max-w-lg', className)}
      onPaste={(e) => {
        if (paste && e.clipboardData.files.length) {
          e.preventDefault()
          void add(Array.from(e.clipboardData.files))
        }
      }}
    >
      <button
        type="button"
        disabled={disabled}
        onClick={() => input.current?.click()}
        onDragOver={(e) => {
          e.preventDefault()
          setDrag(true)
        }}
        onDragLeave={() => setDrag(false)}
        onDrop={(e) => {
          e.preventDefault()
          setDrag(false)
          add(Array.from(e.dataTransfer.files))
        }}
        className={cn(
          'flex w-full flex-col items-center gap-2 rounded-xl border border-dashed p-8 text-sm transition hover:border-primary hover:bg-primary/5 disabled:opacity-50',
          drag && 'border-primary bg-primary/5',
        )}
      >
        <UploadCloud className="mb-2 size-8 text-primary" />
        <span className="font-medium">Click to upload or drag and drop</span>
        <span className="text-xs text-muted-foreground">
          {accept || 'Any file type'} · up to {maxSize / 1024 / 1024} MB
        </span>
      </button>
      <input
        ref={input}
        className="hidden"
        type="file"
        accept={accept}
        multiple={multiple}
        {...(directory ? { webkitdirectory: '' } : {})}
        disabled={disabled}
        aria-label="Choose files"
        onChange={(e) => {
          add(Array.from(e.target.files ?? []))
          e.target.value = ''
        }}
      />
      {error && (
        <p role="alert" className="mt-2 text-xs text-destructive">
          {error}
        </p>
      )}
      <ul className="mt-3 space-y-2">
        {files.map((f) => (
          <li key={f.id} className="flex items-center gap-2 rounded-md border p-2.5 text-sm">
            {f.preview ? (
              <img
                src={f.preview}
                alt={f.file.name}
                className="size-10 shrink-0 rounded object-cover"
              />
            ) : (
              <FileText size={16} />
            )}
            <span className="min-w-0 flex-1 truncate">
              {f.file.name}
              <small className="ml-2 text-muted-foreground">
                {(f.file.size / 1024).toFixed(1)} KB
              </small>
              {f.status === 'error' && (
                <span className="block text-xs text-destructive">{f.error}</span>
              )}
              {f.status === 'uploading' && (
                <span className="mt-2 block h-1 overflow-hidden rounded-full bg-muted">
                  <span
                    className="block h-full bg-primary transition-[width]"
                    style={{ width: `${f.progress ?? 0}%` }}
                  />
                </span>
              )}
            </span>
            {f.status === 'uploading' ? (
              <Loader2 className="size-4 animate-spin" />
            ) : f.status === 'done' ? (
              <Check className="size-4 text-emerald-600" />
            ) : null}
            {f.status === 'error' && (
              <button
                type="button"
                disabled={disabled}
                aria-label={`Retry ${f.file.name}`}
                onClick={() => start(f)}
              >
                <RefreshCw size={14} />
              </button>
            )}
            <button
              type="button"
              aria-label={`Remove ${f.file.name}`}
              onClick={() => {
                requests.current.get(f.id)?.abort()
                const preview = previews.current.get(f.id)
                if (preview) {
                  URL.revokeObjectURL(preview)
                  previews.current.delete(f.id)
                }
                const next = files.filter((v) => v.id !== f.id)
                setFiles(next)
                onFilesChange?.(next.map((v) => v.file))
              }}
            >
              <X size={14} />
            </button>
          </li>
        ))}
      </ul>
    </div>
  )
}

import { Check, X } from 'lucide-react'
import { cn } from '@/lib/utils'
export interface StepItem {
  title: string
  description?: string
  disabled?: boolean
  status?: 'wait' | 'process' | 'finish' | 'error'
  icon?: React.ReactNode
}
export function Steps({
  items,
  current = 0,
  onChange,
  vertical,
  className,
  status = 'process',
}: {
  items: StepItem[]
  current?: number
  onChange?: (step: number) => void
  vertical?: boolean
  className?: string
  status?: StepItem['status']
}) {
  return (
    <ol className={cn('flex gap-4', vertical && 'flex-col', className)} aria-label="Progress">
      {items.map((item, index) => {
        const state =
          item.status ?? (index < current ? 'finish' : index === current ? status : 'wait')
        return (
          <li
            key={index}
            className="flex min-w-0 flex-1 items-start gap-3"
            aria-current={index === current ? 'step' : undefined}
          >
            <button
              type="button"
              disabled={item.disabled || !onChange}
              onClick={() => onChange?.(index)}
              aria-label={`Step ${index + 1}: ${item.title}`}
              className={cn(
                'flex size-8 shrink-0 items-center justify-center rounded-full border text-xs font-semibold',
                state === 'wait'
                  ? 'bg-muted text-muted-foreground'
                  : state === 'error'
                    ? 'border-destructive bg-destructive text-white'
                    : 'border-primary bg-primary text-primary-foreground',
              )}
            >
              {item.icon ??
                (state === 'finish' ? (
                  <Check size={15} />
                ) : state === 'error' ? (
                  <X size={15} />
                ) : (
                  index + 1
                ))}
            </button>
            <div className="flex-1 pt-1">
              <div className="text-sm font-medium">{item.title}</div>
              {item.description && (
                <p className="mt-1 text-xs text-muted-foreground">{item.description}</p>
              )}
              {index < items.length - 1 && (
                <div className={cn('mt-3 bg-border', vertical ? 'h-6 w-px' : 'h-px')} />
              )}
            </div>
          </li>
        )
      })}
    </ol>
  )
}

